"""Fixtures for routing_agent tests"""

import json
from typing import Any
from typing import Dict
from unittest.mock import AsyncMock
from unittest.mock import MagicMock
from unittest.mock import Mock

import pytest
from livekit.agents import JobContext
from livekit.agents import JobProcess
from livekit.protocol.models import ParticipantInfo
from pydantic import SecretStr
from pytest_httpserver import HTTPServer

from commons.enums import AgentType
from commons.monitoring import AgentMonitoring
from commons.schemas.config import EnvironmentConfig
from commons.schemas.config import SecretConfig
from commons.schemas.ingest import CallKind
from commons.schemas.ingest import InboundInputMetadata
from commons.schemas.ingest import OutboundInputMetadata
from commons.schemas.ingest import WebInputMetadata
from commons.schemas.purplefish import CreateEngagementResponse
from commons.services.purplefish_client import PurplefishClient
from tests.commons.mock_purplefish_server import MockPurplefishServer


@pytest.fixture
def mock_environment_config() -> EnvironmentConfig:
    """Create a mock environment configuration"""
    secret_config = SecretConfig(
        cartesia_api_key=SecretStr("test_cartesia_key"),
        deepgram_api_key=SecretStr("test_deepgram_key"),
        openai_api_key=SecretStr("test_openai_key"),
        livekit_api_key=SecretStr("test_livekit_key"),
        livekit_api_secret=SecretStr("test_livekit_secret"),
    )
    return EnvironmentConfig(
        agent_env="test",
        livekit_url="ws://localhost:7880",
        jobs_api_host="http://localhost:8000",
        secrets=secret_config,
    )


@pytest.fixture
def mock_job_context() -> JobContext:
    """Create a mock JobContext"""
    ctx = MagicMock(spec=JobContext)
    ctx.room = Mock()
    ctx.room.name = "test_room_123"
    ctx.job = Mock()
    ctx.job.id = "job_456"
    ctx.proc = Mock(spec=JobProcess)
    ctx.proc.userdata = {}
    ctx.add_shutdown_callback = Mock()
    ctx.shutdown = Mock()
    return ctx


@pytest.fixture
def mock_agent_monitor() -> AgentMonitoring:
    """Create an AgentMonitoring instance for testing"""
    return AgentMonitoring(agent_name="test_agent")


@pytest.fixture
def mock_livekit_client() -> AsyncMock:
    """Create a mock LiveKitClient"""
    client = AsyncMock()
    client.list_participants = AsyncMock(return_value=[])
    client.get_participant_details = AsyncMock(return_value=None)
    client.get_room_info = AsyncMock(return_value=None)
    client.update_room_metadata = AsyncMock()
    client.dispatch_agent = AsyncMock(return_value={"dispatch_id": "dispatch_123"})
    client.close = AsyncMock()
    return client


@pytest.fixture
def mock_purplefish_server(httpserver: HTTPServer) -> MockPurplefishServer:
    """Create a mock Purplefish server using pytest-httpserver"""
    return MockPurplefishServer(httpserver=httpserver)


@pytest.fixture
def purplefish_client(httpserver: HTTPServer) -> PurplefishClient:
    """Create a PurplefishClient connected to the mock server"""
    return PurplefishClient(
        base_url=httpserver.url_for(""),
    )


@pytest.fixture
def sample_sip_participant() -> Dict[str, Any]:
    """Create a sample SIP participant object"""
    participant = Mock()
    participant.identity = "sip_12345"
    participant.kind = ParticipantInfo.Kind.SIP
    participant.name = "SIP Participant"
    participant.attributes = {
        "sip.phoneNumber": "+1234567890",
        "sip.trunkID": "trunk_001",
        "sip.trunkPhoneNumber": "+0987654321",
    }
    return participant


@pytest.fixture
def sample_sip_attributes() -> Dict[str, Any]:
    """Create sample SIP participant attributes"""
    return {
        "sip.phoneNumber": "+1234567890",
        "sip.trunkID": "trunk_001",
        "sip.trunkPhoneNumber": "+0987654321",
    }


@pytest.fixture
def sample_inbound_metadata() -> InboundInputMetadata:
    """Create sample inbound input metadata"""
    return InboundInputMetadata(
        kind=CallKind.INBOUND,
        agent=AgentType.SCREENING,
        candidate_phone_number="+1234567890",
        agent_phone_number="+0987654321",
        agent_trunk_id="trunk_001",
    )


@pytest.fixture
def sample_outbound_metadata() -> OutboundInputMetadata:
    """Create sample outbound input metadata"""
    return OutboundInputMetadata(
        kind=CallKind.OUTBOUND,
        agent=AgentType.SCREENING,
        opportunity_id="opp_789",
        candidate_phone_number="+1234567890",
        agent_trunk_id="trunk_002",
    )


@pytest.fixture
def sample_web_metadata() -> WebInputMetadata:
    """Create sample web input metadata"""
    return WebInputMetadata(
        kind=CallKind.WEB,
        agent=AgentType.SCREENING,
        opportunity_id="opp_web_123",
    )


@pytest.fixture
def sample_engagement_response() -> CreateEngagementResponse:
    """Create sample engagement response"""
    import datetime

    current_time = datetime.datetime.now().isoformat() + "Z"
    return CreateEngagementResponse(
        id="eng_1001",
        created_at=current_time,
        updated_at=current_time,
        profile_id="profile_test",
        room_name="test_room",
        is_newly_created=True,
        agent_name="screening_agent",
    )


@pytest.fixture
def sample_room_metadata_json() -> str:
    """Create sample room metadata as JSON string"""
    metadata = {
        "kind": "outbound",
        "agent": "screening_agent",
        "opportunity_id": "opp_123",
        "candidate_phone_number": "+1234567890",
        "agent_trunk_id": "trunk_001",
    }
    return json.dumps(metadata)
